      {
        "path": "/home/user/labs/git-basics/README.txt",
        "owner": "user",
        "group": "user",
        "mode": "0644",
        "content": "Lab git-basics\\n\\nWork locally only: init the repository, configure identity, add hello.c and Makefile, commit, modify hello.c, inspect the diff, commit again, amend the last commit message, and read git log.\\n"
      }
